// Build 2 Google searches per run (rotating), unless the queue is already full
const MAX_PENDING = 8;          // stop scouting while this many drafts wait for you
const PER_RUN_QUERIES = 2;      // 2 searches x 3 runs/day = ~180/month

// EDIT ME: what kind of posts you want to comment on
const Q = [
  'site:linkedin.com/posts "business analyst" Ireland',
  'site:linkedin.com/posts "product manager" Ireland',
  'site:linkedin.com/posts "data analyst" (Dublin OR Galway)',
  'site:linkedin.com/posts "power bi" dashboard',
  'site:linkedin.com/posts "requirements gathering"',
  'site:linkedin.com/posts n8n automation',
  'site:linkedin.com/posts "AI agents" "business analysis"',
  'site:linkedin.com/posts healthtech Ireland data',
  'site:linkedin.com/posts "stakeholder management" product',
  'site:linkedin.com/posts "data quality" analytics',
];

const rows = $('Read EngagementQueue').all().map(i => i.json).filter(r => r.eq_id);
const pending = rows.filter(r => String(r.status || '').trim().toLowerCase() === 'pending').length;
if (pending >= MAX_PENDING) return [];

const slot = Math.floor(Date.now() / (8 * 3600e3));   // changes every run
return Array.from({ length: PER_RUN_QUERIES }, (_, k) => ({ json: { q: Q[(slot * PER_RUN_QUERIES + k) % Q.length] } }));

// Pick fresh LinkedIn posts from the search results
const PER_RUN = 3, MAX_PENDING = 8, AUTHOR_COOLDOWN_DAYS = 7;
const low = s => String(s || '').trim().toLowerCase();
const hash = s => { let h = 5381; for (const c of String(s)) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(36); };

const rows = $('Read EngagementQueue').all().map(i => i.json).filter(r => r.eq_id);
const pending = rows.filter(r => low(r.status) === 'pending').length;
const room = Math.max(0, Math.min(PER_RUN, MAX_PENDING - pending));
if (!room) return [];

const seenUrl = new Set(rows.map(r => String(r.post_url || '').split('?')[0]));
const cutoff = Date.now() - AUTHOR_COOLDOWN_DAYS * 864e5;
const recentAuthors = new Set(rows.filter(r => Date.parse(r.created_at) > cutoff).map(r => low(r.author)));

const results = $input.all().flatMap(i => i.json.organic || []);
const out = [], used = new Set();
for (const r of results) {
  const url = String(r.link || '').split('?')[0];
  if (!/linkedin\.com\/posts\//.test(url) || seenUrl.has(url) || used.has(url)) continue;
  const text = `${r.title || ''} ${r.snippet || ''}`;
  if (/(we'?re hiring|#hiring|job opening|apply now|job alert)/i.test(text)) continue;   // skip job ads
  if (/tushar/i.test(url)) continue;                                                   // skip own posts
  const slug = (url.match(/\/posts\/([^_/]+)/) || [])[1] || '';
  const author = ((r.title || '').match(/^(.+?)\s+(on LinkedIn|posted on|'s Post)/i) || [])[1]
    || slug.replace(/-[a-z0-9]{4,}$/i, '').replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  if (recentAuthors.has(low(author))) continue;
  used.add(url);
  out.push({ json: {
    eq_id: `eq-${hash(url)}`, post_url: url, author, company: '',
    post_excerpt: String(r.snippet || r.title || '').slice(0, 500),
    context: { author, post_excerpt: String(r.snippet || '').slice(0, 500), post_title: r.title || '',
               note: 'Only an excerpt of the post is available. Comment on what the excerpt actually says; do not assume the rest.' },
  } });
  if (out.length >= room) break;
}
return out;

// One Slack message with every new comment draft
const posts = $('Pick Posts').all().map(i => i.json);
if (!posts.length) return [];
const rows = $('Read EngagementQueue').all().map(i => i.json);  // not used for text, keeps order stable
const drafts = posts.map(p => {
  const r = $('Build Queue Row').all().map(i => i.json).find(x => x.eq_id === p.eq_id);
  return r || p;
});
const lines = drafts.map((r, i) => `*${i + 1}. <${r.post_url}|${r.author || 'post'}>*\n> ${String(r.comment_draft || '(draft failed, see sheet)').replace(/\n/g, '\n> ')}`);
return [{ json: { text: `💬 *${drafts.length} new comment draft(s)* in EngagementQueue\n\n${lines.join('\n\n')}\n\nOpen the post, read it fully, tweak if needed, paste, then set status = Commented.` } }];

const p = $('Current Post').first().json;
const d = $json;
const best = d.best || {};
return [{ json: {
  eq_id: p.eq_id, post_url: p.post_url, author: p.author, company: p.company,
  post_excerpt: p.post_excerpt,
  comment_draft: best.text || '',
  alt_comments: (d.variants || []).map(v => v.text).filter(t => t && t !== best.text).join('\n---\n'),
  pattern: best.pattern || '',
  lint_flags: (best.flags || []).join('; '),
  status: 'Pending', created_at: $now.setZone('Europe/Dublin').toISO(),
  commented_at: '', author_replied: '', your_feedback: '',
} }];
